package io.github.jesterportfolio.hearth.survival.skills;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static io.github.jesterportfolio.hearth.survival.skills.WorldAccessPolicy.*;

final class WorldAccessPolicyTest {
    private Properties base(){var p=new Properties();p.setProperty("format","1");for(var r:Role.values())p.setProperty(r.name().toLowerCase(Locale.ROOT)+".rules","none");return p;}
    private void rule(Properties p,String name,String kind,String ids,int min){p.setProperty("rule."+name+".kind",kind);p.setProperty("rule."+name+".skills",ids);p.setProperty("rule."+name+".minimum",""+min);}
    @Test void homes_bypass_levels_but_never_private_acl(){var p=parse(base());assertTrue(p.evaluate(Role.PUBLIC_HOME,true,Levels.unavailable()).allowed());assertTrue(p.evaluate(Role.PRIVATE_HOME,true,Levels.unavailable()).allowed());assertFalse(p.evaluate(Role.PRIVATE_HOME,false,new Levels(true,Map.of())).allowed());assertFalse(p.evaluate(null,true,new Levels(true,Map.of())).allowed());}
    @Test void resource_without_threshold_still_waits_for_authoritative_load(){var p=parse(base());assertFalse(p.evaluate(Role.RESOURCE,true,Levels.unavailable()).allowed());assertTrue(p.evaluate(Role.RESOURCE,true,new Levels(true,Map.of())).allowed());}
    @Test void multiple_different_thresholds_are_AND_and_include_custom_ids(){var p=base();p.setProperty("resource.rules","mining,craft");rule(p,"mining","specific","auraskills/mining",20);rule(p,"craft","specific","hearth/metallurgy",7);var policy=parse(p);assertEquals(Set.of("auraskills/mining","hearth/metallurgy"),policy.requiredSkills());assertTrue(policy.evaluate(Role.RESOURCE,true,new Levels(true,Map.of("auraskills/mining",20,"hearth/metallurgy",7))).allowed());assertFalse(policy.evaluate(Role.RESOURCE,true,new Levels(true,Map.of("auraskills/mining",40,"hearth/metallurgy",6))).allowed());assertTrue(policy.evaluate(Role.NETHER,true,new Levels(true,Map.of())).allowed());}
    @Test void fixed_average_sum_and_all_use_correct_denominator_and_avoid_int_overflow(){var levels=new Levels(true,Map.of("a/one",20,"a/two",10));assertTrue(new Rule(Kind.AVERAGE,List.of("a/one","a/two"),15).allows(levels));assertFalse(new Rule(Kind.AVERAGE,List.of("a/one","a/two"),16).allows(levels));assertTrue(new Rule(Kind.SUM,List.of("a/one","a/two"),30).allows(levels));assertFalse(new Rule(Kind.ALL,List.of("a/one","a/two"),15).allows(levels));assertTrue(new Rule(Kind.SUM,List.of("a/one","a/two"),Integer.MAX_VALUE).allows(new Levels(true,Map.of("a/one",Integer.MAX_VALUE,"a/two",Integer.MAX_VALUE))));}
    @Test void missing_negative_or_unloaded_values_never_use_default_levels(){var r=new Rule(Kind.SPECIFIC,List.of("a/one"),0);assertFalse(r.allows(Levels.unavailable()));assertFalse(r.allows(new Levels(true,Map.of())));assertFalse(r.allows(new Levels(true,Map.of("a/one",-1))));}
    @Test void typo_unused_or_missing_policy_keys_fail_closed(){var p=base();p.setProperty("resorce.rules","none");assertThrows(IllegalArgumentException.class,()->parse(p));p.remove("resorce.rules");p.remove("nether.rules");assertThrows(RuntimeException.class,()->parse(p));}
    @Test void no_level_balance_is_silently_selected(){var p=parse(base());assertEquals(6,p.rules().size());assertTrue(p.requiredSkills().isEmpty());for(var r:Role.values())assertTrue(p.rules().get(r).isEmpty());}
    @Test void residence_thresholds_duplicate_skills_and_invalid_ids_are_rejected(){var p=base();p.setProperty("private_home.rules","mine");rule(p,"mine","specific","a/mining",1);assertThrows(IllegalArgumentException.class,()->parse(p));assertThrows(IllegalArgumentException.class,()->new Rule(Kind.AVERAGE,List.of("a/mining","a/mining"),1));assertThrows(IllegalArgumentException.class,()->new Rule(Kind.SPECIFIC,List.of("MINING"),1));}
    @Test void end_and_novice_policies_can_be_defined_without_provisioning_worlds(){var p=base();p.setProperty("end.rules","end");p.setProperty("novice_resource.rules","novice");rule(p,"end","sum","a/mining,a/fishing",100);rule(p,"novice","specific","a/mining",0);var policy=parse(p);assertFalse(policy.evaluate(Role.END,true,new Levels(true,Map.of("a/mining",90,"a/fishing",9))).allowed());assertTrue(policy.evaluate(Role.NOVICE_RESOURCE,true,new Levels(true,Map.of("a/mining",0))).allowed());}
}
